let highlighted;function formatItem(e){let t=e.image;if(e.difficulty){const n=t.split(".");t=n[0]+"-"+e.difficulty+"."+n[1]}return`<div class="relative w-100 w-30-l mb4 bg-card shadow-hover"><img alt="${e.title}" src="${t}" title="${e.difficulty}" class="absolute w-20 ml-5 t-50 transform-img"><div class="relative w-75 ml-25 pa4 overflow-hidden"><span class="f6 db">${e.section.toUpperCase()}</span><h3 class="ellipsis f3"><a class="link dim" href="${e.permalink}" title="${e.title}">${e.title}</a></h3><span>${e.summary}</span></div></div>`}function randomHighlighted(){const e=new Set;for(;e.size!=6;)e.add(Math.round(Math.random()*(highlighted.length-1)));document.getElementById("highlightedItems").innerHTML=Array.from(e).map(e=>formatItem(highlighted[e])).join("")}document.getElementById("highlightedButton").addEventListener("click",async e=>{e.preventDefault(),highlighted||(highlighted=(await(await fetch(new URL(document.URL).pathname+"index.json")).json()).highlighted),randomHighlighted()})